pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt1, uint256 amt2) public {
        vm.assume(amt1 > 0);
        amt2 = bound(amt2, 0, type(uint256).max / 2);
        amt1 = bound(amt1, 1, type(uint256).max / 2);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amt1 + amt2);

        bool ok;
        try attacker.attack{value: amt1}(amt2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.getBalance(address(attacker)) == amt1);
    }
}

contract Attacker {
    C c;
    uint256 pending;

    constructor(C _c) { c = _c; }

    function attack(uint256 v2) external payable {
        c.addToBalance{value: msg.value}();
        pending = v2;
        c.withdrawBalance();
    }

    receive() external payable {
        c.addToBalance{value: pending}();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v, uint256 w) public {
        vm.assume(v > 0);
        w = bound(w, 1, v); // re-entered deposit w, must be payable out of the withdrawn v

        Attacker attacker = new Attacker(c, w);

        // normal deposit of v by the attacker
        vm.deal(address(attacker), v);
        attacker.deposit{value: v}();
        assertEq(c.getBalance(address(attacker)), v);

        // withdrawal; the attacker's receive() re-enters addToBalance with w
        bool ok;
        try attacker.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: either the withdrawal reverted, or (if it succeeded)
        // the balance retained is at least the amount re-deposited re-entrantly.
        assertTrue(!ok || c.getBalance(address(attacker)) >= w);
    }
}

contract Attacker {
    C immutable c;
    uint256 immutable w;

    constructor(C c_, uint256 w_) {
        c = c_;
        w = w_;
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function withdraw() external {
        c.withdrawBalance();
    }

    receive() external payable {
        c.addToBalance{value: w}();
    }
}

