pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 depositAmount, uint256 reentrantAmount) public {
        bound(depositAmount, 1, 1e30);
        bound(reentrantAmount, 1, 1e30);
        vm.deal(address(attacker), depositAmount + reentrantAmount);

        attacker.deposit(depositAmount);
        // withdrawal re-enters addToBalance with reentrantAmount; failures swallowed
        attacker.withdraw(reentrantAmount);

        // General rule: total ether held by c never exceeds recorded balances.
        assertTrue(address(c).balance <= c.getBalance(address(attacker)));
    }
}

contract Attacker {
    C c;
    uint256 reentrantAmt;

    constructor(C _c) {
        c = _c;
    }

    function deposit(uint256 amount) external payable {
        c.addToBalance{value: amount}();
    }

    function withdraw(uint256 amount) external {
        reentrantAmt = amount;
        c.withdrawBalance();
    }

    receive() external payable {
        try c.addToBalance{value: reentrantAmt}() {} catch {}
    }
}

